#include "KnowledgeRuntime.hpp"
namespace elysium::knowledge {bool KnowledgeRuntime::add(KnowledgeObject k,std::string&w){if(!k.id||!k.version){w="invalid knowledge";return false;}k.confidence=std::clamp(std::isfinite(k.confidence)?k.confidence:0.0,0.0,1.0);k.legalRisk=std::clamp(std::isfinite(k.legalRisk)?k.legalRisk:0.0,0.0,1.0);return defs_.emplace(k.id,k).second;}bool KnowledgeRuntime::grant(Holding h,std::string&w){if(!h.holder||!defs_.count(h.knowledge)){w="unknown holder/knowledge";return false;}h.confidence=std::clamp(std::isfinite(h.confidence)?h.confidence:0.0,0.0,1.0);for(auto&x:hold_)if(x.holder==h.holder&&x.knowledge==h.knowledge){x.confidence=std::max(x.confidence,h.confidence);x.accessible|=h.accessible;return true;}hold_.push_back(h);return true;}bool KnowledgeRuntime::transfer(StableId f,StableId t,ContentId k,double loss,std::string&w){for(auto&x:hold_)if(x.holder==f&&x.knowledge==k&&x.accessible)return grant({t,k,std::max(0.0,x.confidence-std::max(0.0,loss)),true},w);w="source lacks accessible knowledge";return false;}std::vector<Holding>KnowledgeRuntime::holdings(ContentId k)const{std::vector<Holding>v;for(auto&x:hold_)if(x.knowledge==k)v.push_back(x);std::sort(v.begin(),v.end(),[](auto&a,auto&b){return a.holder<b.holder;});return v;}}
